def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    value = 2019 if v1 > v2 else 2018 if v2 > v1 else None

    return {
        "value": value,
        "trace": {
            "v1_2019": v1,
            "v2_2018": v2,
            "comparison": "2019 > 2018" if v1 > v2 else "2018 > 2019" if v2 > v1 else "equal",
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
